// ---------- Radiation Oncology planned vs delivered ----------
V.radiation=()=>{
  const x=one('radiation'),d=x?.data||{},rx=d.prescription||{},pl=d.planning||{},fr=d.fractions||[],del=fr.filter(z=>z.status==='Delivered'),dose=del.reduce((s,z)=>s+Number(z.delivered_dose_gy||0),0),dx=data('diagnosis'),md=data('mdt'),ord=one('treatment_order');
  const synthetic=/synthetic|demo/i.test([rx.special_instructions||'',S.data?.patient?.mrn||''].join(' '))||S.data?.patient?.mrn==='CCA-0001';
  const hide=pc1ClinicianMode()&&synthetic;
  const cv=(v,suffix='')=>hide?'<span class="clinical-mask">CCA-approved RT value required</span>':esc(pc1FormatMaybe(v,suffix));
  const remaining=rx.fractions?Math.max(0,Number(rx.fractions)-del.length):'—';
  const approvals=['Prescription Draft','RT Oncologist Approved','Simulation / Contouring','Physics QA','RO Final Plan Approval','Ready for Treatment','Course Delivery','Completed'];
  const cur=x?.status==='Completed'?'Completed':x?.status==='Ready for Treatment'?'Ready for Treatment':pl.physician_final_approval==='Approved'?'RO Final Plan Approval':pl.physics_qa==='Approved'?'Physics QA':rx.status==='RT Oncologist Approved'?'RT Oncologist Approved':'Prescription Draft';
  return title('Radiation Oncology — Prescription, Approval & Course','Planned prescription is separated from delivered treatment. TPS/OIS performs planning/dose calculation; CCA OS reconciles approvals and delivery evidence.')+pc1ModeBanner()+`<div class="alert blue"><b>TPS/OIS boundary:</b> contouring, dose calculation and machine control are not recreated here. Store/reconcile prescription, plan version, QA approvals, DICOM-RT references and delivered fractions.</div><br>${pc1StatusSteps(approvals,cur)}<br><div class="planned-delivered">${card('PLANNED RT',kv('Course / phase',esc(`${rx.course_id||x?.id||'—'} • phase ${rx.treatment_phase||'—'}`))+kv('Site / laterality',esc(`${rx.site||'—'} • ${rx.laterality||'—'}`))+kv('Intent / technique',esc(`${rx.intent||'—'} • ${rx.modality||'—'} / ${rx.technique||'—'}`))+kv('Total planned dose',cv(rx.total_dose_gy,' Gy'))+kv('Dose / fraction',cv(rx.dose_per_fraction_gy,' Gy'))+kv('Planned fractions',hide?'<span class="clinical-mask">CCA-approved fractionation required</span>':esc(rx.fractions||'—'))+kv('Planned start',esc(rx.planned_start||'—')))}${card('DELIVERED RT',kv('Delivered fractions',esc(del.length))+kv('Remaining',hide?'<span class="clinical-mask">Depends on approved fractionation</span>':esc(remaining))+kv('Cumulative delivered dose',hide?'<span class="clinical-mask">Synthetic dose hidden</span>':esc(`${dose.toFixed(2)} Gy`))+kv('Actual first fraction',fmt(del[0]?.date_time))+kv('Last fraction',fmt(del.at(-1)?.date_time))+kv('Interruptions',esc(fr.filter(z=>z.status!=='Delivered').length)))}</div><br><div class="grid g3">${card('Cancer / MDT context',kv('Diagnosis',esc(dx.cancer_type||'—'))+kv('Stage',esc(dx.stage_group||'—'))+kv('MDT recommendation',esc(md.recommendation||'—'))+kv('Concurrent systemic order',esc(ord?.data?.order_no||'None linked')))}${card('Plan version / DICOM-RT',kv('Plan version',esc(pl.plan_version||'Not recorded'))+kv('RTSTRUCT',esc(pl.dicom_refs?.RTSTRUCT||'Pending integration'))+kv('RTPLAN',esc(pl.dicom_refs?.RTPLAN||'Pending integration'))+kv('RTDOSE',esc(pl.dicom_refs?.RTDOSE||'Pending integration')))}${card('Approvals',kv('Physics QA',badge(pl.physics_qa,statusColor(pl.physics_qa)))+kv('Physics QA by',esc(pl.physics_qa_by?.name||pl.physics_qa_by||'—'))+kv('RO final approval',badge(pl.physician_final_approval,statusColor(pl.physician_final_approval)))+kv('RO approved by',esc(pl.physician_approval_by?.name||pl.physician_approval_by||'—'))+kv('Approved at',fmt(pl.physician_approval_at)))}</div><div class="row">${S.role==='Radiation Oncology'?'<button class="btn" data-act="rt-edit">Edit Prescription</button><button class="btn primary" data-act="rt-sign">Sign RT Prescription</button><button class="btn" data-act="rt-plan-ready">Record Planning / RO Approval</button>':''}${S.role==='Radiation Physicist'?'<button class="btn primary" data-act="rt-physics-qa">Record Physics QA</button>':''}${S.role==='Radiation Technologist'?'<button class="btn primary" data-act="rt-fraction">Deliver Fraction</button><button class="btn" data-act="rt-missed">Miss / Reschedule Fraction</button>':''}</div><br>${card('Fraction-by-fraction delivery',`<div class="table-wrap"><table><thead><tr><th>Fraction</th><th>Status</th><th>Date/time</th><th>Delivered dose</th><th>Cumulative</th><th>Verified by</th><th>IGRT / setup / toxicity / interruption</th></tr></thead><tbody>${fr.map((z,i)=>`<tr><td>${esc(z.fraction_number)}</td><td>${badge(z.status,statusColor(z.status))}</td><td>${fmt(z.date_time)}</td><td>${hide?'<span class="clinical-mask">Hidden</span>':esc(`${z.delivered_dose_gy} Gy`)}</td><td>${hide?'<span class="clinical-mask">Hidden</span>':esc(`${fr.slice(0,i+1).reduce((s,a)=>s+Number(a.delivered_dose_gy||0),0).toFixed(2)} Gy`)}</td><td>${esc(z.verified_by?.name||z.verified_by||'—')}</td><td>${esc([z.image_guidance_performed?'Image guidance performed':'',z.setup_variation,z.toxicity,z.reason,z.rescheduled_to?`Rescheduled ${z.rescheduled_to}`:''].filter(Boolean).join(' • '))}</td></tr>`).join('')||'<tr><td colspan="7">No fractions recorded.</td></tr>'}</tbody></table></div>`)}`;
};

