/* --------------------------------------------------------------------------
   V12.2-PC1.1 — CLINICIAN UX REMEDIATION
   Presentation-only. No clinical decision, persistence, safety, or authorization
   semantics are changed here. JSON remains an internal transport/storage format;
   clinician-facing screens render it as labelled clinical information.
   -------------------------------------------------------------------------- */

function humanLabel(k){
  const map={
    id:'Record ID',mrn:'MRN',dob:'Date of birth',cancer_type:'Cancer',primary_site:'Primary site',
    histology:'Histology',stage_t:'T',stage_n:'N',stage_m:'M',stage_group:'Stage group',ecog:'ECOG',
    clinical_content_status:'Clinical content status',synthetic_test_only:'Synthetic QA only',
    total_dose_gy:'Total dose (Gy)',dose_per_fraction_gy:'Dose / fraction (Gy)',fractions:'Fractions',
    target_volumes:'Target volumes',organs_at_risk:'Organs at risk',oar_constraints:'OAR constraints',
    simulation_requirement:'Simulation',image_guidance:'Image guidance',treatment_phase:'Phase',
    procedure:'Procedure',preop_requirements:'Pre-operative requirements',required_imaging_pathology:'Required imaging / pathology',
    blood_requirement:'Blood requirement',operative_record_fields:'Operative record fields',
    workflow_fields:'Workflow fields',state_machine:'Workflow states',planned_delivered_schema:'Planned vs delivered fields',
    approval_chain:'Approval pathway',readiness_rule_schema:'Treatment readiness rules',monitoring_requirements:'Monitoring requirements',
    dose_modification_rules:'Dose modification rules',hold_parameters:'Readiness thresholds',items:'Treatment sequence',
    governance:'Clinical review',route:'Route',schedule:'Schedule',monitoring_plan:'Monitoring plan',
    source_ref:'Source reference',governance_status:'Clinical approval',line_of_therapy:'Line of therapy'
  };
  return map[k]||String(k||'').replace(/_/g,' ').replace(/\b\w/g,m=>m.toUpperCase());
}
function humanScalar(v){
  if(v===null||v===undefined||v==='')return '—';
  if(typeof v==='boolean')return v?'Yes':'No';
  return String(v);
}
function renderHumanObject(obj,opts={}){
  if(obj===null||obj===undefined||obj==='')return '<span class="muted">Not recorded</span>';
  if(Array.isArray(obj)){
    if(!obj.length)return '<span class="muted">None recorded</span>';
    if(obj.every(x=>typeof x!=='object'||x===null))return `<ul class="clean-list">${obj.map(x=>`<li>${esc(humanScalar(x))}</li>`).join('')}</ul>`;
    return `<div class="human-stack">${obj.map((x,i)=>`<div class="human-item"><div class="mini muted">${opts.itemLabel||'Item'} ${i+1}</div>${renderHumanObject(x,opts)}</div>`).join('')}</div>`;
  }
  if(typeof obj!=='object')return `<span>${esc(humanScalar(obj))}</span>`;
  const hidden=new Set(opts.hide||['synthetic_test_only','clinician_review_mode']);
  const rows=Object.entries(obj).filter(([k,v])=>!hidden.has(k)&&v!==undefined).map(([k,v])=>{
    const nested=typeof v==='object'&&v!==null;
    return nested
      ? `<div class="human-group"><div class="human-label">${esc(humanLabel(k))}</div><div class="human-value">${renderHumanObject(v,opts)}</div></div>`
      : `<div class="human-row"><span>${esc(humanLabel(k))}</span><b>${esc(humanScalar(v))}</b></div>`;
  }).join('');
  return rows||'<span class="muted">No information recorded</span>';
}
function renderSimpleTable(headers,rows){
  return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Not configured</td></tr>`}</tbody></table></div>`;
}
function renderTemplateHuman(x,d){
  const synthetic=pc1SyntheticTemplate(x),mask=pc1ClinicianMode()&&synthetic;
  if(x.category==='Radiation Template'){
    const approval=(d.governance||{}),planned=d.planned_delivered_schema||{};
    return `<div class="grid g2">
      ${card('Prescription structure',kv('Site',esc(mask?'CCA site / indication required':d.site||'—'))+kv('Laterality',esc(d.laterality||'—'))+kv('Intent',esc(mask?'CCA-approved intent required':d.intent||'—'))+kv('Modality',esc(d.modality||'—'))+kv('Technique',esc(mask?'CCA-approved technique required':d.technique||'—'))+kv('Dose / fraction',mask?'<span class="clinical-mask">CCA-approved prescription required</span>':esc(`${d.total_dose_gy??'—'} Gy • ${d.dose_per_fraction_gy??'—'} Gy × ${d.fractions??'—'}`)))}
      ${card('Planning & approval',kv('Simulation',esc(d.simulation_requirement||'—'))+kv('Image guidance',esc(mask?'CCA configuration required':d.image_guidance||'—'))+kv('RO review',badge(approval.radiation_oncology_review?.status||'Pending',statusColor(approval.radiation_oncology_review?.status)))+kv('Physics review',badge(approval.physics_review?.status||'Pending',statusColor(approval.physics_review?.status))))}
    </div><br>${card('Targets & organs at risk',`<div class="grid g2"><div><div class="section-label">Target volumes</div>${renderHumanObject(mask?['CCA target-volume definition required']:(d.target_volumes||[]))}</div><div><div class="section-label">Organs at risk / constraints</div>${renderHumanObject(mask?['CCA OAR / constraint configuration required']:[...(d.organs_at_risk||[]),...(d.oar_constraints||[])])}</div></div>`)}<br>${card('Course workflow',renderHumanObject(d.approval_chain||[]))}`;
  }
  if(x.category==='Surgical Template'){
    return `<div class="grid g2">
      ${card('Surgical plan',kv('Procedure',esc(mask?'CCA procedure options required':d.procedure||'—'))+kv('Indication',esc(d.indication||'—'))+kv('Intent',esc(mask?'CCA-approved intent required':d.intent||'—'))+kv('Site / laterality',esc(mask?'CCA site/laterality options required':`${d.site||'—'} • ${d.laterality||'—'}`))+kv('Approach',esc(d.approach||'—'))+kv('Anaesthesia',esc(d.anesthesia||'—')))}
      ${card('Pre-operative requirements',renderHumanObject(d.preop_requirements||[])+`<div class="section-label top-gap">Required imaging / pathology</div>`+renderHumanObject(d.required_imaging_pathology||[]))}
    </div><br>${card('Operative record — captured separately after surgery',`<div class="field-chip-wrap">${(d.operative_record_fields||[]).map(f=>`<span class="field-chip">${esc(humanLabel(f))}</span>`).join('')}</div><div class="mini muted top-gap">The planned procedure remains preserved; the operative record documents what actually happened.</div>`)}`;
  }
  if(x.category==='Continuous Therapy Template'){
    return `<div class="grid g2">${card('Therapy structure',kv('Mode',esc(d.mode||'—'))+kv('Drug',esc(mask?'CCA-approved medicine required':d.drug||'—'))+kv('Route',esc(d.route||'—'))+kv('Schedule',esc(mask?'CCA-approved schedule required':d.schedule||'—'))+kv('Monitoring',esc(mask?'CCA monitoring plan required':d.monitoring_plan||'—')))}${card('Lifecycle',renderHumanObject(d.state_machine||[]))}</div><br>${card('Information captured during treatment',`<div class="field-chip-wrap">${(d.workflow_fields||[]).map(f=>`<span class="field-chip">${esc(humanLabel(f))}</span>`).join('')}</div>`)}`;
  }
  return renderHumanObject(d);
}
function renderReadinessResult(j){
  const ev=j?.evaluation||j||{}, rules=ev.rule_results||[], blockers=ev.blockers||[], warnings=ev.warnings||[];
  return `<div class="grid g2">${card('Decision summary',kv('Outcome',blockers.length?badge('Blocked','red'):badge('No configured blocker','green'))+kv('Lab source',esc(ev.lab_source_id||'—'))+kv('Protocol source',esc(ev.thresholds_source||ev.protocol_id||'Institution Content Master')))}${card('Messages',`${blockers.length?`<div class="alert red"><b>Blockers</b>${renderHumanObject(blockers)}</div>`:''}${warnings.length?`<div class="alert amber"><b>Review items</b>${renderHumanObject(warnings)}</div>`:''}${!blockers.length&&!warnings.length?'<div class="alert green">No blocker or review message returned by the configured rules.</div>':''}`)}</div>${rules.length?`<br>${card('Rule evaluation',renderSimpleTable(['Domain','Field','Current','Rule','Outcome'],rules.map(r=>[esc(r.category||'—'),esc(humanLabel(r.field||'')),esc(`${r.current??'—'} ${r.unit||''}`),esc(`${r.operator||''} ${r.threshold??''} ${r.unit||''}`),badge(r.outcome||r.status||'—',statusColor(r.outcome||r.status))])) )}`:''}`;
}

