V.protocols=()=>{const p=data('protocol_library'),f=S.formulary||{items:[]};return title('Protocol & Formulary Governance','Institutional clinical content is versioned and maintained as structured fields — not raw JSON.')+`<div class="grid g2">${card('Treatment protocol',renderHumanObject(p))}${card('Formulary master',renderHumanObject(f))}</div>`;};

// Role-focused navigation. Everyday care pages stay primary; technical/governance pages are collapsed.
const PC11_PRIMARY={
  'Front Desk':['summary','registration','consent','appointments','queue','journey','documents'],
  'Nurse Navigator':['summary','intake','medications','documents','care_plan','toxicity'],
  'Medical Oncology':['summary','consultation','diagnosis','diagnostic_orders','mdt','treatment_plan','order','readiness','toxicity','response'],
  'Surgical Oncology':['summary','surgery','mdt','response'],
  'Radiation Oncology':['summary','radiation','mdt'],
  'Oncology Pharmacy':['pharmacy','trace'],
  'Day Care / Infusion Nurse':['daycare','trace','toxicity'],
  'Radiation Physicist':['radiation'],
  'Radiation Technologist':['radiation'],
  'Surgical Nurse':['surgery'],
  'MDT Coordinator':['mdt','nexus','guideline_pathway','staging_review'],
  'Radiologist':['radiology_orders','radiology_report','documents'],
  'Laboratory / Phlebotomy':['lab_orders','lab_result'],
  'Pathology':['pathology','documents']
};
const PC11_LABELS={
  summary:'Patient Summary',consultation:'Consultation',diagnosis:'Diagnosis & Staging',diagnostic_orders:'Investigations',mdt:'MDT / Tumour Board',treatment_plan:'Treatment Plan',order:'Treatment Order',readiness:'Treatment Readiness',toxicity:'Toxicity / Dose Changes',response:'Response Assessment',surgery:'Surgical Plan & Operative Record',radiation:'RT Course',pharmacy:'Pharmacy Verification & Preparation',trace:'Order → Delivery',daycare:'Treatment Day / MAR',intake:'Vitals & History',medications:'Medications & Allergies',documents:'Documents',care_plan:'Care Plan',registration:'Registration & Routing',consent:'Consent',appointments:'Scheduling',queue:'Queue',journey:'Patient Journey',nexus:'NEXUS',guideline_pathway:'Guideline Pathway',staging_review:'Staging',radiology_orders:'Radiology Queue',radiology_report:'Radiology Report',lab_orders:'Lab Queue',lab_result:'Lab Result',pathology:'Pathology / Molecular'
};
function pc11AllMenu(){
  let menu=[...(MENUS[S.role]||[])];
  if(S.role!=='External Consultant')menu.unshift(['TASKS','tasks','My Tasks / Alerts']);
  if(S.role==='Medical Oncology')menu.unshift(['AI','ai_search','AI Record Search']);
  if(['Medical Oncology','Surgical Oncology','Radiation Oncology','MDT Coordinator','Oncology Pharmacy','Day Care / Infusion Nurse','Inpatient Oncology Nurse','Radiation Technologist','Radiation Physicist'].includes(S.role))menu.unshift(['REPORTS','report_library','Report Templates']);
  if(['Medical Oncology','Oncology Pharmacy'].includes(S.role))menu.unshift(['CONTENT','regimen_library','Regimen Library']);
  if(S.role==='Oncology Pharmacy')menu.unshift(['CONTENT','formulary_master','Institution Formulary']);
  if(S.role==='Radiation Oncology')menu.unshift(['CONTENT','rt_template_library','RT Template Library']);
  if(S.role==='Surgical Oncology')menu.unshift(['CONTENT','surgical_template_library','Surgical Template Library']);
  if(S.role==='Hospital Management / Admin')menu.unshift(['CONTENT','content_library','Clinical Content Manager'],['CONTENT','formulary_master','Institution Formulary']);
  return menu;
}
function pc11SimplifyNav(){
  const base=pc11AllMenu(), primKeys=PC11_PRIMARY[S.role]||base.slice(0,7).map(x=>x[1]);
  const byKey=new Map(base.map(x=>[x[1],x]));
  if(['Medical Oncology','Surgical Oncology','Radiation Oncology'].includes(S.role)){
    byKey.set('nexus',['FUTURE CDS','nexus','NEXUS']);byKey.set('guideline_pathway',['FUTURE CDS','guideline_pathway','Guideline Pathway']);byKey.set('staging_review',['FUTURE CDS','staging_review','Staging']);
  }
  const primary=primKeys.map(k=>byKey.get(k)).filter(Boolean), primarySet=new Set(primary.map(x=>x[1]));
  const secondary=base.filter(x=>!primarySet.has(x[1])&&x[1]!=='role_surface');
  if((!S.page||S.page==='role_surface')&&primary.length){S.page=primary[0][1];localStorage.setItem('cca_v12_page',S.page);renderPage();}
  let html='<div class="nav-group">Clinical workspace</div>';
  html+=primary.map(([,key,label])=>`<button class="navbtn ${key===S.page?'active':''}" data-page="${key}">${esc(PC11_LABELS[key]||label)}</button>`).join('');
  if(['Medical Oncology','Surgical Oncology','Radiation Oncology'].includes(S.role)){
    html+=`<div class="nav-group">Future CDS</div><button class="navbtn ${S.page==='nexus'?'active':''}" data-page="nexus">NEXUS <span class="nav-pill">Frontend</span></button>`;
  }
  if(secondary.length){html+=`<details class="nav-more" ${secondary.some(x=>x[1]===S.page)?'open':''}><summary>More tools</summary>${secondary.map(([,key,label])=>`<button class="navbtn ${key===S.page?'active':''}" data-page="${key}">${esc(label)}</button>`).join('')}</details>`;}
  $('#nav').innerHTML=html; bind();
}
const pc11BaseRenderApp=renderApp;
renderApp=function(){pc11BaseRenderApp();pc11SimplifyNav();pc1UpdateModeButton();};

// Clear, role-appropriate summary with next-step shortcuts.
const pc11BaseSummary=V.summary;
V.summary=()=>{
  const p=S.data.patient||{},dx=data('diagnosis'),tp=one('treatment_plan'),ord=one('treatment_order'),ready=one('readiness'),ph=one('pharmacy'),inf=one('infusion'),to=data('toxicity'),resp=data('response');
  const actions=S.role==='Medical Oncology'?`<button class="btn primary" data-page="consultation">Open Consultation</button><button class="btn" data-page="treatment_plan">Treatment Plan</button><button class="btn" data-page="readiness">Readiness</button>`:S.role==='Day Care / Infusion Nurse'?`<button class="btn primary" data-page="daycare">Open Treatment Day</button>`:S.role==='Oncology Pharmacy'?`<button class="btn primary" data-page="pharmacy">Open Pharmacy Worklist</button>`:'';
  return title('Patient Summary',`${esc(p.name||'Patient')} • ${esc(p.mrn||'')} — current clinical state and the next work that matters.`,actions)
    +`<div class="clinical-hero"><div><div class="eyebrow">Current cancer state</div><h3>${esc(dx.cancer_type||'Diagnosis not recorded')}</h3><div>${esc([dx.primary_site,dx.histology,dx.stage_group].filter(Boolean).join(' • ')||'Site / histology / stage pending')}</div></div><div class="hero-status">${badge(dx.disease_status||'Disease status pending',statusColor(dx.disease_status))}</div></div><br>`
    +`<div class="grid g4">${card('Treatment plan',kv('Status',badge(tp?.status||'Not started',statusColor(tp?.status)))+kv('Intent',esc(tp?.data?.intent||dx.treatment_intent||'—')))}${card('Current order',kv('Order',esc(ord?.data?.order_no||'None'))+kv('Regimen',esc(ord?.data?.regimen||'—'))+kv('Cycle / day',esc(ord?`C${ord.data.cycle} D${ord.data.day}`:'—')))}${card('Treatment readiness',kv('Status',badge(ready?.status||'Not assessed',statusColor(ready?.status)))+kv('Decision',esc(ready?.data?.decision||'—')))}${card('Delivery',kv('Pharmacy',badge(ph?.status||'Not started',statusColor(ph?.status)))+kv('Administration',badge(inf?.status||'Not started',statusColor(inf?.status))))}</div><br>`
    +`<div class="grid g2">${card('Safety & toxicity',kv('Active toxicities',esc((to.events||[]).filter(x=>x.outcome!=='Resolved').length))+kv('Latest ANC',esc(data('lab').anc??'—'))+kv('Latest response',esc((resp.assessments||[]).at(-1)?.response_category||'Baseline / pending')))}${card('What happens next',pc11NextStep())}</div>`;
};
function pc11NextStep(){
  if(S.role==='Medical Oncology'){if(!one('treatment_plan'))return '<div class="next-step"><b>1. Complete assessment</b><span>Confirm diagnosis, staging and investigations, then create the treatment plan.</span></div>';if(!one('treatment_order'))return '<div class="next-step"><b>2. Create treatment order</b><span>Use the clinician-approved plan and governed regimen/version.</span></div>';if(!one('readiness')||!['Ready','Approved','Proceed as Planned'].some(x=>String(one('readiness')?.status||one('readiness')?.data?.decision||'').includes(x)))return '<div class="next-step"><b>3. Review treatment readiness</b><span>Check toxicity, final labs and regimen-specific rules before treatment.</span></div>';return '<div class="next-step"><b>Continue treatment workflow</b><span>Order is ready for downstream Pharmacy / Day Care execution.</span></div>';}
  if(S.role==='Oncology Pharmacy')return '<div class="next-step"><b>Verify → Prepare → Dispense</b><span>Work only from the signed treatment-order version.</span></div>';
  if(S.role==='Day Care / Infusion Nurse')return '<div class="next-step"><b>Pre-check → MAR → Observe</b><span>Document each ordered item, reaction and completion state.</span></div>';
  return '<div class="next-step"><b>Continue your role worklist</b><span>Use the left navigation for the next patient-care step.</span></div>';
}

// Final action interceptor removes remaining raw-object presentation from report/readiness/external case previews.
const pc11BaseHandle=handle;
handle=async function(el){
  const a=el.dataset.act;
  try{
    if(a==='preview-report'){
      const r=await api('/api/report/render?template='+encodeURIComponent(el.dataset.id)+'&patient='+encodeURIComponent(S.pid)),h=r.header||{};
      const sections=(r.sections||[]).map(sec=>`<div class="card report-section"><h3>${esc(sec.title)}</h3>${renderHumanObject(sec.data)}</div>`).join('<br>');
      modal(h.template_name||'Generated Report',`<div class="report-header"><div><div class="eyebrow">Patient</div><h3>${esc(h.patient_name||'')}</h3><div>${esc(`MRN ${h.mrn||'—'} • DOB ${h.dob||'—'}`)}</div><div>${esc([h.diagnosis,h.stage].filter(Boolean).join(' • '))}</div></div><div class="mini muted">Generated ${fmt(h.generated_at)}<br>${esc(h.generated_by?.name||h.generated_by?.role||'')}<br>${esc(h.template_id||'')} v${esc(h.template_version||'')}</div></div><br>${sections}<br><div class="alert amber">This report is derived from signed/versioned source records. Correct the source record or addendum rather than editing the report.</div><div class="row"><button class="btn primary" id="rptPrint">Print</button></div>`);
      $('#rptPrint').onclick=()=>window.print();return;
    }
    if(a==='preview-readiness'||a==='save-readiness'){
      const lab=one('lab'),reg=(S.content?.templates||[]).find(x=>x.id===S.selectedRegimenId);if(!reg?.orderable){toast('Select an approved orderable regimen first',true);S.page='regimen_library';renderApp();return}if(!lab||lab.status!=='Final'){toast('A finalized laboratory result is required before readiness can be evaluated',true);return}
      const decisions=['Proceed as Planned','Proceed with Modification','Hold','Delay','Omit','Substitute','Stop'];
      const save=async decision=>{const payload={template_id:reg.id,decision,reason:val('rd_reason')||'Reviewed by Medical Oncology',sign:a==='save-readiness'};const j=await action(a==='preview-readiness'?'preview_readiness':'save_readiness',id('readiness'),payload);closeModal();modal(a==='preview-readiness'?'Treatment Readiness Preview':'Treatment Readiness Saved',renderReadinessResult(j));if(a==='save-readiness')await refresh();};
      const ld=lab.data||{},u=ld.units||{},src=`<div class="source-strip"><b>Final lab</b><span>${esc(lab.id)} • ${esc(ld.date||'—')}</span><span>ANC ${esc(ld.anc??'—')} ${esc(u.anc||'')}</span><span>Platelets ${esc(ld.platelets??'—')} ${esc(u.platelets||'')}</span><span>Bilirubin ${esc(ld.bilirubin??'—')} ${esc(u.bilirubin||'')}</span></div>`;
      if(a==='preview-readiness'){modal('Preview Treatment Readiness',`${fld('Regimen','rd_reg',reg.name+' v'+reg.version,'text','readonly')}${src}${txt('Review note','rd_reason','Review current finalized labs and protocol criteria')}<button class="btn primary" id="rdSave">Evaluate Readiness</button>`);$('#rdSave').onclick=()=>save('Proceed as Planned');}
      else{modal('Sign Treatment Readiness',`${fld('Regimen','rd_reg',reg.name+' v'+reg.version,'text','readonly')}${src}${sel('Decision','rd_dec','Proceed as Planned',decisions)}${txt('Clinical rationale','rd_reason','Relevant clinical status, finalized labs, toxicity, medication/allergy context and protocol criteria reviewed.')}<button class="btn primary" id="rdSave">Sign Decision</button>`);$('#rdSave').onclick=()=>save(val('rd_dec'));}return;
    }
    if(a==='open-external'){
      const j=await api('/api/mdt/external-view?access='+encodeURIComponent(val('ext_token')));$('#externalResult').innerHTML=`<div class="alert green"><b>${esc(j.case_code)}</b> • expires ${fmt(j.expires_at)}</div><div class="grid g2">${card('Diagnosis',renderHumanObject(j.diagnosis||{}))}${card('MDT Recommendation',renderHumanObject(j.mdt||{}))}</div><br>${card('Evidence',kv('Pathology',esc(j.pathology_summary||'—'))+kv('Imaging',esc(j.imaging_summary||'—')))}`;return;
    }
  }catch(e){toast(e.message,true);return;}
  return pc11BaseHandle(el);
};

// Replace template modal once more so every category has a clinical view, never raw JSON.
const pc11PrevHandle=handle;
handle=async function(el){
  if(el.dataset.act==='view-template'){
    const x=(S.content?.templates||[]).find(z=>z.id===el.dataset.id);if(!x)return;const d=x.data||{},src=contentSource(x.source_id),synthetic=pc1SyntheticTemplate(x),mask=pc1ClinicianMode()&&synthetic;
    const identity=card('Template',kv('Cancer / disease',esc(x.disease||'—'))+kv('Use',esc(x.subtype||x.category||'—'))+kv('Version',esc(x.version||'—'))+kv('Clinical approval',esc(d.clinical_content_status||x.governance_status||'—'))+kv('Orderable',x.orderable?badge('Yes','green'):badge('No','amber')));
    const source=card('Clinical governance',kv('Owner',esc(x.clinical_owner||'CCA clinical owner required'))+kv('Source',esc(src.name||x.source_id||'—'))+kv('Status',badge(x.status,statusColor(x.status)))+(S.role==='Hospital Management / Admin'?kv('Source reference',esc(x.source_ref||'—')):''));
    let body='';
    if(x.category==='Regimen'){
      const dose=q=>mask?'<span class="clinical-mask">CCA-approved value required</span>':`${esc(q.protocol_dose??'—')} ${esc(q.protocol_unit||'')}`;
      body=card('Treatment sequence',renderSimpleTable(['Seq','Section','Medication','Dose basis','Protocol value','Route / preparation','Timing'],(d.items||[]).map(q=>[esc(q.sequence),esc(q.group),`<b>${esc(q.drug)}</b>`,esc(q.dose_basis||'—'),dose(q),mask?'<span class="clinical-mask">CCA preparation required</span>':esc(`${q.route||'—'}${q.diluent?` • ${q.diluent}`:''}${q.volume_ml?` • ${q.volume_ml} mL`:''}`),mask?'<span class="clinical-mask">CCA instruction required</span>':esc(q.timing||q.special_instructions||'—')])))
        +`<br>${card('Monitoring',renderSimpleTable(['When','Domain','Requirement','Status'],(d.monitoring_requirements||[]).map(r=>[esc(r.phase||'—'),esc(r.category||'—'),esc(r.requirement||'—'),esc(r.clinical_value_status||'CCA configuration required')])))}`
        +`<br>${card('Dose modification',renderSimpleTable(['Domain','Trigger','Action options','Status'],(d.dose_modification_rules||[]).map(r=>[esc(r.domain||'—'),esc(r.trigger||'—'),esc((r.action_options||[]).join(' / ')||'Protocol-specific'),esc(r.clinical_value_status||'CCA configuration required')])))}`;
    }else body=renderTemplateHuman(x,d);
    modal(x.name,pc1ModeBanner()+`<div class="grid g2">${identity}${source}</div><br>${body}`);return;
  }
  return pc11PrevHandle(el);
};

